remarks.code:
 // Connection string for account should be in the application settings:
 <appSettings>
   <add key="myaccountconnection" value="UseDevelopmentStorage=True" />
 </appSettings>

 // store to: (account).blob.core.windows.net/photos/johnsmith
 storage = new SimpleBlobStore("myaccountconnection", "photos");
 storage.Save("johnsmith", File.ReadAllBytes("johnsmith.jpg"), "image/jpeg");
 
 // store to: (account).blob.core.windows.net/photos/highres/johnsmith
 storage = new SimpleBlobStore("myaccountconnection", "photos", "highres");
 storage.Save("johnsmith", File.ReadAllBytes("johnsmith_large.jpg"), "image/jpeg");
 
 // store to: (account).blob.core.windows.net/photos/thumbnails/64x64/johnsmith
 storage = new SimpleBlobStore("myaccountconnection", "photos", "thumbnails/64x64");
 storage.Save("johnsmith", File.ReadAllBytes("johnsmith_thumb.jpg"), "image/jpeg");
 
 // list from: (account).blob.core.windows.net/photos/thumbnails
 storage = new SimpleBlobStore("myaccountconnection", "photos", "thumbnails");
 var photos = storage.ListAll();
 
 // load from: (account).blob.core.windows.net/photos/johnsmith
 storage = new SimpleBlobStore"myaccountconnection", ("photos");
 byte[] photo = storage.Load("johnsmith");
 
 // load from: (account).blob.core.windows.net/photos/highres/johnsmith
 storage = new SimpleBlobStore("myaccountconnection", "photos", "highres");
 using (FileStream fs = new FileStream("photo.jpg"))
 {
   storage.Load("johnsmith", fs);
 }
